/*
 * prog52_bfs_grid.c
 *
 * A tiny breadth‑first‑search on a fixed 5×6 grid.
 * The program is called with four integer arguments:
 *
 *     prog52_bfs_grid  start_row  start_col  target_row  target_col
 *
 * Rows are numbered 0‑4, columns 0‑5.
 *
 * The grid is hard‑coded; only the character ‘#’ is treated as an obstacle.
 * All other cells are free (the original binary used a zero‑initialised
 * array, which is equivalent to a grid filled with '.' characters).
 *
 * Output:
 *   - "dist=%d"   – the length of the shortest path,
 *   - "UNREACHABLE" – when the target cannot be reached,
 *   - "INVALID_CELL" – when any coordinate is out of bounds or lies on '#'.
 *
 * The behaviour matches the original obfuscated binary exactly.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define ROWS 5
#define COLS 6
#define MAX_CELLS (ROWS * COLS)

/* Fixed grid – only ‘#’ blocks movement.  All other cells are free. */
static char grid[ROWS][COLS] = {
    {'.', '.', '.', '.', '.', '.'},
    {'.', '.', '.', '.', '.', '.'},
    {'.', '.', '.', '.', '.', '.'},
    {'.', '.', '.', '.', '.', '.'},
    {'.', '.', '.', '.', '.', '.'}
};

int main(int argc, char *argv[])
{
    if (argc != 5) {
        puts("INVALID_CELL");
        return 0;
    }

    int sr = (int)strtol(argv[1], NULL, 10);
    int sc = (int)strtol(argv[2], NULL, 10);
    int tr = (int)strtol(argv[3], NULL, 10);
    int tc = (int)strtol(argv[4], NULL, 10);

    if (sr < 0 || sr >= ROWS || sc < 0 || sc >= COLS ||
        tr < 0 || tr >= ROWS || tc < 0 || tc >= COLS) {
        puts("INVALID_CELL");
        return 0;
    }

    if (grid[sr][sc] == '#' || grid[tr][tc] == '#') {
        puts("INVALID_CELL");
        return 0;
    }

    bool visited[ROWS][COLS] = { false };
    int  dist[ROWS][COLS] = { 0 };
    int q_row[MAX_CELLS];
    int q_col[MAX_CELLS];
    int head = 0, tail = 0;

    visited[sr][sc] = true;
    dist[sr][sc] = 0;
    q_row[tail] = sr;
    q_col[tail] = sc;
    ++tail;

    const int dr[4] = { -1, 1, 0, 0 };
    const int dc[4] = {  0, 0,-1, 1 };

    while (head < tail) {
        int r = q_row[head];
        int c = q_col[head];
        ++head;

        if (r == tr && c == tc) {
            printf("dist=%d\n", dist[r][c]);
            return 0;
        }

        for (int d = 0; d < 4; ++d) {
            int nr = r + dr[d];
            int nc = c + dc[d];

            if (nr < 0 || nr >= ROWS || nc < 0 || nc >= COLS)
                continue;
            if (visited[nr][nc])
                continue;
            if (grid[nr][nc] == '#')
                continue;

            visited[nr][nc] = true;
            dist[nr][nc] = dist[r][c] + 1;
            q_row[tail] = nr;
            q_col[tail] = nc;
            ++tail;
        }
    }

    puts("UNREACHABLE");
    return 0;
}
